#include <stdio.h>
#include <stdlib.h>

int parent[10];
int rank_[10];

int find(int x) {
    if (parent[x] == x) {
        return x;
    }
    return parent[x] = find(parent[x]);
}

void union_(int x, int y) {
    int root_x = find(x);
    int root_y = find(y);
    if (root_x != root_y) {
        if (rank_[root_x] < rank_[root_y]) {
            parent[root_x] = root_y;
        } else if (rank_[root_x] > rank_[root_y]) {
            parent[root_y] = root_x;
        } else {
            parent[root_y] = root_x;
            rank_[root_x]++;
        }
    }
}

int main(int argc, char **argv) {
    for (int i = 0; i < 10; i++) {
        parent[i] = i;
        rank_[i] = 0;
    }
    for (int i = 1; i < argc; i++) {
        if (strcmp(argv[i], "U") == 0) {
            int x = atoi(argv[i + 1]);
            int y = atoi(argv[i + 2]);
            union_(x, y);
            i += 2;
        } else if (strcmp(argv[i], "F") == 0) {
            int x = atoi(argv[i + 1]);
            int root = find(x);
            printf("FIND %d=%d\n", x, root);
            i += 1;
        }
    }
    return 0;
}
